SELECT s.id, s.merchant_id, m.name AS merchant_name, s.name, s.address,
       s.business_status, s.status
FROM store s
JOIN merchant m ON s.merchant_id = m.id


        AND s.merchant_id = #{query.merchantId}


        AND s.business_status = #{query.businessStatus}


        AND s.status = #{query.status}


ORDER BY s.id DESC
LIMIT #{page.offset}, #{page.size}

SELECT COUNT(*) FROM store s


        AND s.merchant_id = #{query.merchantId}


        AND s.business_status = #{query.businessStatus}


        AND s.status = #{query.status}
